from pathlib import Path
import base64
import gzip
import subprocess

payload = ""
patch_path = Path('/tmp/cinematic-detail.patch')
patch_path.write_bytes(gzip.decompress(base64.b64decode(payload)))
subprocess.run(['patch', '-p1', '-i', str(patch_path)], check=True)
for staged in [Path('scripts/apply_cinematic_detail_system_nav.py'), Path('.github/workflows/one-shot-cinematic-detail-system-nav.yml')]:
    if staged.exists(): staged.unlink()
print('Applied cinematic detail/system navigation patch.')
